const fs=require('fs'),path=require('path');
const dir=__dirname,base='https://www.licitatii-insolventa.ro';
const entities={amp:'&',quot:'"',apos:"'",lt:'<',gt:'>',nbsp:' ',ndash:'–',mdash:'—',hellip:'…'};
function decode(x=''){return x.replace(/&(#x[\da-f]+|#\d+|\w+);/gi,(m,k)=>k[0]==='#'?String.fromCodePoint(k[1]==='x'?parseInt(k.slice(2),16):+k.slice(1)):entities[k]??m)}
function clean(x=''){return decode(x.replace(/<[^>]*>/g,' ')).replace(/\s+/g,' ').trim()}
function match(x,re){return x.match(re)?.[1]||''}
function field(x,c){return clean(match(x,new RegExp('<(?:div|a|span)[^>]*class="'+c+'[^" ]*(?: [^"]*)?"[^>]*>([\\s\\S]*?)</(?:div|a|span)>')))}
const errors=[];let requests=0;
async function fetchPage(url){for(let n=0;n<3;n++){try{requests++;const r=await fetch(url,{signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error('HTTP '+r.status);return await r.text()}catch(e){if(n===2)throw e;await new Promise(r=>setTimeout(r,1500*(n+1)))}}}
const catNames={afaceri:'Afaceri',auto:'Auto',imobiliare:'Imobiliare',industrial:'Industrial',office:'Office',altele:'Altele'};
function parseList(html){return html.split(/<div class="list-prod [^"]*">/).slice(1).map(c=>{const url=match(c,/<h3[^>]*>\s*<a href="([^"]*)"/);const title=clean(match(c,/<h3[^>]*>\s*<a[^>]*>([\s\S]*?)<\/a>/));const priceText=field(c,'price');const n=priceText.match(/[\d,]+\.\d+/);const loc=field(c,'loc');const lm=loc.match(/^(.*?) in (.*?) \((.*?)\)$/);const image=match(c,/<img[^>]*src="([^"]*)"/);return {id:'ins-'+match(url,/_i(\d+)/),source:'INSOLVENȚĂ',sourceUrl:url,title,category:catNames[url.split('/')[3]]||'Altele',subcategory:field(c,'category'),price:n?Number(n[0].replace(/,/g,'')):null,currency:/Euro/i.test(priceText)?'EUR':/LEI/i.test(priceText)?'RON':null,priceText,county:lm?.[2]||null,locality:lm?.[1]||null,country:lm?.[3]||null,location:loc,image:image.includes('no-image')?null:image,description:field(c,'desc'),seller:clean(match(c,/<div class="author">[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/)),publishedLabel:field(c,'date'),attributes:{}}})}
function input(h,n){return decode(match(h,new RegExp('name="'+n+'" value="([^"]*)"')))}
function detail(row,h){const attrs={};const block=match(h,/<div id="custom_fields">([\s\S]*?)<div id="plugin-details">/);for(const m of block.matchAll(/<div class="ins">\s*<span>([^<]*):<\/span>([\s\S]*?)<\/div>/g))attrs[clean(m[1])]=clean(m[2]);row.attributes=attrs;row.description=clean(decode(input(h,'desc')))||row.description;row.publishedAt=input(h,'pub_date')||null;row.expiresAt=input(h,'expire_date')||null;row.auctionDate=attrs['Data licitatie']||null;row.auctionTime=attrs['Ora licitatie']||null;row.county=input(h,'region')||row.county;row.locality=input(h,'city')||row.locality;row.brand=attrs['Marca']||null;row.year=/^\d{4}$/.test(attrs['An fabricatie'])?+attrs['An fabricatie']:null;row.fuel=attrs['Combustibil']||null;row.area=attrs['Suprafata']||attrs['Suprafata teren']||null;row.detailFetched=true;}
function save(rows,more={}){fs.writeFileSync(path.join(dir,'listings.json'),JSON.stringify(rows,null,2));fs.writeFileSync(path.join(dir,'coverage.json'),JSON.stringify({source:base,checkedAt:new Date().toISOString(),referenceDate:'2026-10-12',expected:2309,count:rows.length,detailCount:rows.filter(r=>r.detailFetched).length,requests,errors,...more},null,2))}
(async()=>{let rows=[];for(let p=1;p<=47;p++){try{const h=p===1?fs.readFileSync(path.join(dir,'search.html'),'utf8'):await fetchPage(base+'/cauta/iPage,'+p);fs.writeFileSync(path.join(dir,'page-'+p+'.html'),h);rows.push(...parseList(h));console.log('page',p,rows.length);await new Promise(r=>setTimeout(r,120));}catch(e){errors.push({page:p,error:e.message})}}rows=[...new Map(rows.map(r=>[r.id,r])).values()];save(rows,{pages:47});let next=0,done=0;await Promise.all(Array.from({length:4},async()=>{while(next<rows.length){const r=rows[next++];try{detail(r,await fetchPage(r.sourceUrl))}catch(e){errors.push({id:r.id,error:e.message})}done++;if(done%100===0){save(rows,{pages:47});console.log('details',done,'/',rows.length)}await new Promise(r=>setTimeout(r,180))}}));save(rows,{pages:47,complete:errors.length===0});console.log('COMPLETE',rows.length,errors.length)})();

